CREATE OR REPLACE TRIGGER trg_interdit
BEFORE DELETE ON produits
BEGIN
  RAISE_APPLICATION_ERROR(-20001, 'Suppression interdite');
END;
/

CREATE OR REPLACE TRIGGER trg_prix
BEFORE INSERT OR UPDATE OF prix ON produits
FOR EACH ROW
BEGIN
  IF :NEW.prix IS NULL OR :NEW.prix <= 0 THEN
    RAISE_APPLICATION_ERROR(-20030, 'Prix invalide');
  END IF;
END;
/

CREATE OR REPLACE TRIGGER trg_produits_journal
AFTER INSERT OR UPDATE OR DELETE ON produits
FOR EACH ROW
DECLARE
  v_op journal.operation%TYPE;
  v_id produits.id%TYPE;
BEGIN
  IF INSERTING THEN
    v_op := 'INSERT'; v_id := :NEW.id;
  ELSIF UPDATING THEN
    v_op := 'UPDATE'; v_id := :NEW.id;
  ELSE
    v_op := 'DELETE'; v_id := :OLD.id;     -- :NEW est vide à la suppression
  END IF;

  INSERT INTO journal (table_nom, operation, ligne_id, utilisateur, date_op)
  VALUES ('PRODUITS', v_op, v_id, USER, SYSDATE);
END;
/

