CREATE OR REPLACE TRIGGER trg_client_suppression
BEFORE DELETE ON clients
FOR EACH ROW
DECLARE
  v_nb NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_nb FROM commandes WHERE client_id = :OLD.id;
  IF v_nb > 0 THEN
    RAISE_APPLICATION_ERROR(-20032, 'Ce client a des commandes : suppression refusée');
  END IF;
END;
/

